#include "../reactor-guided/engine.hpp"
// reactor-random: полностью случайные поля. Первая треть — равновероятный выбор состояния клетки, остальные — случайные веса U^8.
// Попытки rrLoops, seed rrSeed. Проверка: горение и остывание, оба порядка обработки (test из engine.hpp).
int main(int argc,char**argv){long long loops=PI("rrLoops");loadFuels();rng.seed((unsigned)PI("rrSeed"));double budget=PR.budget,venting=PR.av;for(int i=0;i<N;i++){if(i%19)a[i].push_back(i-1);if(i%19<18)a[i].push_back(i+1);if(i>=19)a[i].push_back(i-19);if(i<285)a[i].push_back(i+19);}
 map<string,long long>stats;map<string,long long>failed;double best=-1e99;ofstream log("tested.csv");log<<"attempt,mode,cost_Qa,status,reason,tick,net_B_per_tick\n";
 for(long long z=0;z<loops;z++){if(z&&z%200000==0)cerr<<"попыток "<<z<<"\n";bool weighted=z>=loops/3;string mode=weighted?"random_weights":"uniform";stats[mode+"_generated"]++;array<double,12>cdf{};double sum=0;if(weighted)for(int j=0;j<12;j++){double v=U();sum+=pow(v,8);cdf[j]=sum;}string g(N,'.');array<int,128>n{};for(int i=0;i<N;i++){int j;if(weighted){double v=U()*sum;j=(int)(lower_bound(cdf.begin(),cdf.end(),v)-cdf.begin());}else j=rng()%12;g[i]=types[j];n[g[i]]++;}
 if(!n['1']&&!n['2']&&!n['4']){stats[mode+"_no_fuel"]++;continue;}if((n['1']&&!PI("anA1"))||(n['2']&&!PI("anA2"))||(n['4']&&!PI("anA4"))){stats[mode+"_rod_not_allowed"]++;continue;}double cost=venting+PR.fuel(n)+PR.parts(n);if(cost>budget){stats[mode+"_over_budget"]++;continue;}stats[mode+"_simulated"]++;Check r=test(g,0);if(r.ok){auto q=test(g,1);if(!q.ok)r=q;else r.net=min(r.net,q.net);}log<<z<<','<<mode<<','<<cost<<','<<r.ok<<','<<r.reason<<','<<r.tick<<','<<r.net<<'\n';if(!r.ok){failed[r.reason]++;continue;}stats[mode+"_passed"]++;if(r.net>best){best=r.net;string gk=g;ofstream f("best.txt");f<<setprecision(12)<<"net_B "<<best<<" cost_Qa "<<cost<<" attempt "<<z<<'\n';for(int y=0;y<16;y++)f<<gk.substr(y*19,19)<<'\n';}}
 ofstream out("stats.txt");for(auto [k,v]:stats)out<<k<<' '<<v<<'\n';for(auto[k,v]:failed)out<<"failure_"<<k<<' '<<v<<'\n';out<<"best_net_B "<<best<<'\n';cout<<"done\n";return 0;}
